{
  "type": "sim",
  "engine": "widget",
  "caption": "调整节点数 n，观察 AVL 树高度上限与模拟值",
  "html": "<style>
.widget-container {
  display: flex;
  flex-direction: column;
  align-items: center;
  font-family: system-ui, sans-serif;
}
.widget-container svg {
  background: var(--bg);
  border: 1px solid var(--line);
  border-radius: 4px;
}
.controls {
  margin-top: 10px;
  display: flex;
  align-items: center;
  gap: 10px;
}
.controls label {
  color: var(--ink);
  font-size: 14px;
}
.controls input[type='range'] {
  width: 200px;
}
</style>
<div class='widget-container'>
  <svg id='chart' width='600' height='400' viewBox='0 0 600 400' xmlns='http://www.w3.org/2000/svg'></svg>
  <div class='controls'>
    <label>节点数 n = <span id='nValue'>10</span></label>
    <input type='range' id='nSlider' min='1' max='30' step='1' value='10'>
  </div>
</div>
<script>
// 数据计算
function computeTheory() {
  const nMax = 30;
  const avlUpper = [];
  const complete = [];
  const log2 = [];
  for (let n = 1; n <= nMax; n++) {
    avlUpper.push(1.44 * Math.log2(n + 2));
    complete.push(Math.floor(Math.log2(n)) + 1);
    log2.push(Math.log2(n));
  }
  return { avlUpper, complete, log2 };
}

// AVL 树实现
class AVLNode {
  constructor(key) {
    this.key = key;
    this.left = null;
    this.right = null;
    this.height = 1;
  }
}

class AVLTree {
  constructor() {
    this.root = null;
  }
  height(node) {
    return node ? node.height : 0;
  }
  updateHeight(node) {
    node.height = Math.max(this.height(node.left), this.height(node.right)) + 1;
  }
  rotateRight(y) {
    const x = y.left;
    const T2 = x.right;
    x.right = y;
    y.left = T2;
    this.updateHeight(y);
    this.updateHeight(x);
    return x;
  }
  rotateLeft(x) {
    const y = x.right;
    const T2 = y.left;
    y.left = x;
    x.right = T2;
    this.updateHeight(x);
    this.updateHeight(y);
    return y;
  }
  getBalance(node) {
    return node ? this.height(node.left) - this.height(node.right) : 0;
  }
  insert(node, key) {
    if (!node) return new AVLNode(key);
    if (key < node.key) {
      node.left = this.insert(node.left, key);
    } else if (key > node.key) {
      node.right = this.insert(node.right, key);
    } else {
      return node;
    }
    this.updateHeight(node);
    const balance = this.getBalance(node);
    if (balance > 1 && key < node.left.key) {
      return this.rotateRight(node);
    }
    if (balance < -1 && key > node.right.key) {
      return this.rotateLeft(node);
    }
    if (balance > 1 && key > node.left.key) {
      node.left = this.rotateLeft(node.left);
      return this.rotateRight(node);
    }
    if (balance < -1 && key < node.right.key) {
      node.right = this.rotateRight(node.right);
      return this.rotateLeft(node);
    }
    return node;
  }
  insert(key) {
    this.root = this.insert(this.root, key);
  }
}

function shuffle(arr) {
  for (let i = arr.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [arr[i], arr[j]] = [arr[j], arr[i]];
  }
}

function simulateAVLHeights() {
  const nMax = 30;
  const heights = [];
  for (let n = 1; n <= nMax; n++) {
    const arr = Array.from({length: n}, (_, i) => i + 1);
    shuffle(arr);
    const tree = new AVLTree();
    for (const val of arr) {
      tree.insert(val);
    }
    heights.push(tree.root ? tree.root.height : 0);
  }
  return heights;
}

const theory = computeTheory();
const simHeights = simulateAVLHeights();

function update(n) {
  const svg = document.getElementById('chart');
  svg.innerHTML = '';
  const margin = { left: 60, right: 20, top: 20, bottom: 40 };
  const width = 600 - margin.left - margin.right;
  const height = 400 - margin.top - margin.bottom;
  const xScale = (nVal) => margin.left + (nVal - 1) / 29 * width;
  const yScale = (h) => margin.top + height - (h / 10) * height;

  // 坐标轴
  const xAxisY = margin.top + height;
  svg.innerHTML += `<line x1='${margin.left}' y1='${xAxisY}' x2='${margin.left + width}' y2='${xAxisY}' style='stroke: var(--line); stroke-width: 1;'/>`;
  svg.innerHTML += `<line x1='${margin.left}' y1='${margin.top}' x2='${margin.left}' y2='${xAxisY}' style='stroke: var(--line); stroke-width: 1;'/>`;

  // x 刻度
  for (let nVal = 1; nVal <= 30; nVal += 5) {
    const x = xScale(nVal);
    svg.innerHTML += `<line x1='${x}' y1='${xAxisY}' x2='${x}' y2='${xAxisY + 5}' style='stroke: var(--line); stroke-width: 1;'/>`;
    svg.innerHTML += `<text x='${x}' y='${xAxisY + 20}' text-anchor='middle' style='fill: var(--ink); font-size: 12px;'>${nVal}</text>`;
  }
  // y 刻度
  for (let h = 0; h <= 10; h += 2) {
    const y = yScale(h);
    svg.innerHTML += `<line x1='${margin.left - 5}' y1='${y}' x2='${margin.left}' y2='${y}' style='stroke: var(--line); stroke-width: 1;'/>`;
    svg.innerHTML += `<text x='${margin.left - 10}' y='${y + 4}' text-anchor='end' style='fill: var(--ink); font-size: 12px;'>${h}</text>`;
  }

  // 轴标签
  svg.innerHTML += `<text x='${margin.left + width / 2}' y='${400 - 5}' text-anchor='middle' style='fill: var(--ink); font-size: 14px;'>节点数 n</text>`;
  svg.innerHTML += `<text x='${15}' y='${margin.top + height / 2}' text-anchor='middle' transform='rotate(-90, 15, ${margin.top + height / 2})' style='fill: var(--ink); font-size: 14px;'>高度 h</text>`;

  // 曲线
  // AVL 上界
  let d = '';
  for (let i = 0; i < theory.avlUpper.length; i++) {
    const nVal = i + 1;
    const x = xScale(nVal);
    const y = yScale(theory.avlUpper[i]);
    if (i === 0) d += `M ${x} ${y}`;
    else d += ` L ${x} ${y}`;
  }
  svg.innerHTML += `<path d='${d}' style='stroke: var(--accent); stroke-width: 2; fill: none; stroke-dasharray: 4,2;' />`;

  // 完全二叉树
  d = '';
  for (let i = 0; i < theory.complete.length; i++) {
    const nVal = i + 1;
    const x = xScale(nVal);
    const y = yScale(theory.complete[i]);
    if (i === 0) d += `M ${x} ${y}`;
    else d += ` L ${x} ${y}`;
  }
  svg.innerHTML += `<path d='${d}' style='stroke: var(--line); stroke-width: 2; fill: none;' />`;

  // log2 参考
  d = '';
  for (let i = 0; i < theory.log2.length; i++) {
    const nVal = i + 1;
    const x = xScale(nVal);
    const y = yScale(theory.log2[i]);
    if (i === 0) d += `M ${x} ${y}`;
    else d += ` L ${x} ${y}`;
  }
  svg.innerHTML += `<path d='${d}' style='stroke: var(--ink); stroke-width: 1; fill: none; stroke-dasharray: 2,2;' />`;

  // 散点
  for (let i = 0; i < simHeights.length; i++) {
    const nVal = i + 1;
    const x = xScale(nVal);
    const y = yScale(simHeights[i]);
    const isCurrent = (nVal === n);
    const r = isCurrent ? 6 : 4;
    const opacity = isCurrent ? 1 : 0.5;
    svg.innerHTML += `<circle cx='${x}' cy='${y}' r='${r}' style='fill: var(--accent); opacity: ${opacity};' />`;
  }

  // 当前 n 信息
  const avlVal = theory.avlUpper[n-1];
  const simVal = simHeights[n-1];
  const completeVal = theory.complete[n-1];
  svg.innerHTML += `<text x='${margin.left + width - 10}' y='${margin.top + 20}' text-anchor='end' style='fill: var(--ink); font-size: 14px;'>n = ${n}</text>`;
  svg.innerHTML += `<text x='${margin.left + width - 10}' y='${margin.top + 40}' text-anchor='end' style='fill: var(--accent); font-size: 14px;'>AVL 上界: ${avlVal.toFixed(2)}</text>`;
  svg.innerHTML += `<text x='${margin.left + width - 10}' y='${margin.top + 60}' text-anchor='end' style='fill: var(--accent); font-size: 14px;'>模拟高度: ${simVal}</text>`;
  svg.innerHTML += `<text x='${margin.left + width - 10}' y='${margin.top + 80}' text-anchor='end' style='fill: var(--line); font-size: 14px;'>完全二叉树: ${completeVal}</text>`;

  // 图例
  const legendX = margin.left + 10;
  const legendY = margin.top + 10;
  svg.innerHTML += `<line x1='${legendX}' y1='${legendY}' x2='${legendX + 20}' y2='${legendY}' style='stroke: var(--accent); stroke-width: 2; stroke-dasharray: 4,2;' />`;
  svg.innerHTML += `<text x='${legendX + 25}' y='${legendY + 4}' style='fill: var(--ink); font-size: 12px;'>AVL 上界</text>`;
  svg.innerHTML += `<line x1='${legendX}' y1='${legendY + 20}' x2='${legendX + 20}' y2='${legendY + 20}' style='stroke: var(--line); stroke-width: 2;' />`;
  svg.innerHTML += `<text x='${legendX + 25}' y='${legendY + 24}' style='fill: var(--ink); font-size: 12px;'>完全二叉树</text>`;
  svg.innerHTML += `<line x1='${legendX}' y1='${legendY + 40}' x2='${legendX + 20}' y2='${legendY + 40}' style='stroke: var(--ink); stroke-width: 1; stroke-dasharray: 2,2;' />`;
  svg.innerHTML += `<text x='${legendX + 25}' y='${legendY + 44}' style='fill: var(--ink); font-size: 12px;'>log₂(n)</text>`;
  svg.innerHTML += `<circle cx='${legendX + 10}' cy='${legendY + 60}' r='4' style='fill: var(--accent); opacity: 0.5;' />`;
  svg.innerHTML += `<text x='${legendX + 25}' y='${legendY + 64}' style='fill: var(--ink); font-size: 12px;'>模拟 AVL 树（示意）</text>`;
}

// 初始化
const slider = document.getElementById('nSlider');
const nValue = document.getElementById('nValue');
slider.addEventListener('input', function() {
  const n = parseInt(this.value);
  nValue.textContent = n;
  update(n);
});
update(parseInt(slider.value));
</script>"
}
